#!/usr/bin/env python3
import math, random, sys

# Physical constants
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8         # m s^-1
M_sun = 1.98847e30       # kg
hbar = 1.054571817e-34   # J s
k_B = 1.380649e-23       # J K^-1

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def isco_radius(M, a):
    """Prograde ISCO radius for Kerr (|a|<M)."""
    Z1 = 1 + (1 - a**2)**(1/3) * ((1 + a)**(1/3) + (1 - a)**(1/3))
    Z2 = math.sqrt(3 * a**2 + Z1**2)
    if a >= 0:
        return M * (3 + Z2 - math.sqrt((3 - Z1) * (3 + Z1 + 2 * Z2)))
    else:
        return M * (3 + Z2 + math.sqrt((3 - Z1) * (3 + Z1 + 2 * Z2)))

def photon_sphere_radius(M, a):
    """Radius of the unstable photon sphere (Lyttleton radius)."""
    if a >= 0:
        return M * (3 - math.sqrt(3 * a**2 + 3))
    else:
        return M * (3 + math.sqrt(3 * a**2 + 3))

def horizon_radius(M, a):
    """Event horizon r_+ = M + sqrt(M^2 - a^2)."""
    return M + math.sqrt(M**2 - a**2)

def horizon_area(r):
    """Area of a spherical horizon A = 4π r^2."""
    return 4 * math.pi * r**2

def hawking_temperature(M):
    """Hawking temperature T = ħ c^3 / (8π G k_B M)."""
    return hbar * c**3 / (8 * math.pi * G * k_B * M)

def planck_length():
    """Planck length l_P = sqrt(ħ G / c^3)."""
    return math.sqrt(hbar * G / c**3)

def bh_entropy(r_s, r_h, T):
    """S = k_B * A / l_P^2, where A is the horizon area.
    Here we use the temperature to compute the total entropy via
    S = k_B * c^3 A / (4 G ħ) = A k_B / l_P^2.
    """
    area = horizon_area(r_h)
    lP2 = planck_length()**2
    return k_B * area / lP2

def main():
    # Mass of the supermassive black hole (Sgr A*)
    M = 4.31e6 * M_sun  # kg
    # Spin parameter (dimensionless, |a|<1)
    a = 0.9
    r_s = schwarzschild_radius(M)
    r_hor = horizon_radius(M, a)
    r_isco = isco_radius(M, a)
    r_ph = photon_sphere_radius(M, a)
    T = hawking_temperature(M)
    lP = planck_length()
    S = bh_entropy(r_s, r_hor, T)

    print(f"Schwarzschild radius (r_s): {r_s:.3e} m")
    print(f"Event horizon radius (r_+): {r_hor:.3e} m")
    print(f"ISCO radius: {r_isco:.3e} m")
    print(f"Photon‑sphere radius: {r_ph:.3e} m")
    print(f"Hawking temperature: {T:.3e} K")
    print(f"Planck length: {lP:.3e} m")
    print(f"Bekenstein‑Hawking entropy: {S:.3e} J/K")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import os, json, math, numpy as np

# ---------------------------------------------------------------------
# Physical constants (SI) – required by the spec, even if not used later
# ---------------------------------------------------------------------
G = 6.67430e-11          # m³·kg⁻¹·s⁻²
c = 2.99792458e8        # m·s⁻¹
hbar = 1.054571817e-34  # J·s
k_B = 1.380649e-23      # J·K⁻¹
M_sun = 1.98847e30      # kg

def load_gwtc_catalog():
    """Load the GWTC catalog JSON and return the list of events.
    The environment variable GWTC_CATALOG_PATH must point to a JSON file with the
    structure {"events": [{"event_id": ..., "mass_1_source": ..., "mass_2_source": ..., ...}, ...]}
    """
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path:
        raise RuntimeError('Environment variable GWTC_CATALOG_PATH not set')
    with open(path, 'r') as f:
        data = json.load(f)
    return data.get('events', [])

def total_mass(event):
    m1 = event.get('mass_1_source')
    m2 = event.get('mass_2_source')
    if None in (m1, m2):
        return None
    return float(m1) + float(m2)

def main():
    events = load_gwtc_catalog()
    results = []
    for ev in events:
        M_tot = total_mass(ev)
        if M_tot is None:
            continue
        results.append(M_tot)
    if not results:
        print('No valid events found')
        return
    # Simple sanity check: non‑negative mass
    for M in results:
        assert M > 0, f'Unexpected non‑positive total mass: {M}'
    print(f"Analyzed {len(results)} events with valid total mass.")

if __name__ == '__main__':
    main()

